<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {markets,path,fmt} from '../data'
import {session,openModal} from '../session'
import Coin from '../components/Coin.vue'
import Chart from '../components/Chart.vue'
const route=useRoute(),query=ref(''),category=ref('全部'),favorites=ref([]),interval=ref('1小時'),orderType=ref('市價'),leverage=ref('10'),amount=ref(''),limit=ref(''),percent=ref(0),expiry=ref('60'),records=ref('合約倉位'),error=ref('')
const mode=computed(()=>route.params.mode||'futures'),pair=computed(()=>markets.find(m=>m.id===route.params.symbol)||markets[0]),rows=computed(()=>markets.filter(m=>(category.value==='全部'||category.value==='自選'&&favorites.value.includes(m.id)||m.category===category.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())))
const title=computed(()=>({futures:'合約',spot:'現貨',options:'期權'}[mode.value]))
function favorite(id){favorites.value=favorites.value.includes(id)?favorites.value.filter(v=>v!==id):[...favorites.value,id]}
function order(side){error.value='';if(!session.loggedIn){error.value='請先登入本地演示帳戶';return}if(!Number.isFinite(Number(amount.value))||Number(amount.value)<=0){error.value='請輸入有效的下單金額';return}if(orderType.value==='限價'&&Number(limit.value)<=0){error.value='請輸入有效的委託價格';return}openModal('order',`${side} · ${pair.value.name}`,{symbol:'USD',min:1,max:100000,amount:amount.value,name:`${title.value} ${side} ${pair.value.name}`,description:`${orderType.value} · ${mode.value==='futures'?leverage.value+'x':mode.value==='options'?expiry.value+' 秒':'現貨'}`})}
</script>
<template><div class="trading-terminal"><div class="instrument-bar"><div class="coin-label"><Coin :symbol="pair.symbol"/><strong>{{ $tr(pair.name) }}</strong></div><strong :class="pair.change<0?'negative':'positive'">{{ $tr(fmt(pair.price)) }}</strong><span :class="pair.change<0?'negative':'positive'">{{ $tr(pair.change) }}%</span><span><small>{{ $tr("24h 漲跌") }}</small>{{ $tr(fmt(pair.price*.0135)) }}</span><span><small>{{ $tr("24h 最高") }}</small>{{ $tr(fmt(pair.price*1.064)) }}</span><span><small>{{ $tr("24h 最低") }}</small>{{ $tr(fmt(pair.price*.979)) }}</span><span><small>{{ $tr("24h 成交量") }}</small>{{ $tr(pair.volume) }}</span><RouterLink :to="path('/copytrade')">{{ $tr("跟單交易 ↗") }}</RouterLink></div>
<div class="terminal-grid"><aside class="terminal-panel pair-panel"><input v-model="query" :aria-label="$tr(&quot;搜尋交易對&quot;)" :placeholder="$tr(&quot;搜尋&quot;)"/><nav class="trade-modes"><RouterLink v-for="(label,key) in {futures:'合約',options:'期權',spot:'現貨'}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $tr(label) }}</RouterLink></nav><div class="pair-categories"><button v-for="c in ['自選','全部','加密貨幣','外匯','股票']" :key="c" :class="{active:category===c}" @click="category=c">{{ $tr(c) }}</button></div><div class="pair-list"><div v-for="m in rows" :key="m.id" class="pair-row"><button :aria-label="$tr((favorites.includes(m.id)?'取消自選 ':'加入自選 ')+m.name)" :aria-pressed="favorites.includes(m.id)" @click="favorite(m.id)">{{ $tr(favorites.includes(m.id)?'★':'☆') }}</button><RouterLink :to="path('/trade/'+mode+'/'+m.id)"><span class="coin-label"><Coin :symbol="m.symbol"/><span>{{ $tr(m.name) }}<small class="mini-label">{{ $tr(m.volume) }}</small></span></span><span>{{ $tr(fmt(m.price)) }}<small :class="m.change<0?'negative':'positive'">{{ $tr(m.change) }}%</small></span></RouterLink></div><div v-if="!rows.length" class="empty">{{ $tr("沒有符合的交易對") }}</div></div></aside>
<section class="terminal-panel chart-panel"><div class="timeframes"><button v-for="t in ['1分鐘','5分鐘','15分鐘','30分鐘','1小時','1天','1週','1月','1年']" :class="{active:interval===t}" @click="interval=t">{{ $tr(t) }}</button><span>{{ $tr("MA 指標") }}</span></div><Chart :price="pair.price" :interval="interval"/></section>
<section class="terminal-panel orderbook"><h2>{{ $tr("委託簿") }}</h2><div class="book-head"><span>{{ $tr("價格 (USD)") }}</span><span>{{ $tr("數量") }}</span><span>{{ $tr("累計") }}</span></div><div v-for="n in 9" :key="'ask'+n" class="book-row" :style="{'--depth':(n*7+13)+'%'}"><span class="negative">{{ $tr(fmt(pair.price+(10-n)*pair.price*.00002)) }}</span><span>{{ $tr((n*.0013).toFixed(4)) }}</span><span>{{ $tr((n*.0037).toFixed(4)) }}</span></div><div class="book-price negative">{{ $tr(fmt(pair.price)) }} ↓ <small>≈ {{ $tr(fmt(pair.price)) }}{{ $tr(" USD") }}</small></div><div v-for="n in 9" :key="'bid'+n" class="book-row bid" :style="{'--depth':(n*9)+'%'}"><span class="positive">{{ $tr(fmt(pair.price-n*pair.price*.00002)) }}</span><span>{{ $tr((n*.0017).toFixed(4)) }}</span><span>{{ $tr((n*.0041).toFixed(4)) }}</span></div></section>
<section class="terminal-panel order-panel"><nav class="trade-modes"><RouterLink v-for="(label,key) in {futures:'合約下單',options:'期權下單',spot:'現貨'}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $tr(label) }}</RouterLink></nav><div class="summary-line"><span class="mini-label">{{ $tr("簡易模式") }}</span><span class="tag-chip">{{ $tr(session.mode) }}{{ $tr("帳戶") }}</span></div><div class="tabs"><button v-for="t in ['市價','限價']" :class="{active:orderType===t}" @click="orderType=t">{{ $tr(t) }}</button></div><div v-if="mode==='futures'" class="two-cols"><label>{{ $tr("槓桿") }}<select v-model="leverage"><option v-for="n in [1,5,10,20,50,100]" :value="String(n)">{{ $tr(n) }}{{ $tr("x") }}</option></select></label><label>{{ $tr("保證金模式") }}<select :aria-label="$tr(&quot;保證金模式&quot;)"><option :value="&quot;全倉&quot;">{{ $tr("全倉") }}</option><option :value="&quot;逐倉&quot;">{{ $tr("逐倉") }}</option></select></label></div><label v-if="mode==='options'">{{ $tr("到期時間") }}<select v-model="expiry"><option v-for="n in [60,180,300,600]" :value="String(n)">{{ $tr(n) }}{{ $tr(" 秒") }}</option></select></label><label>{{ $tr("價格 (USD)") }}<input v-model="limit" :disabled="orderType==='市價'" :placeholder="$tr(orderType==='市價'?'以當前市場價格成交':'請輸入價格')" inputmode="decimal"/></label><label>{{ $tr("金額 (USD)") }}<input v-model="amount" inputmode="decimal" :placeholder="$tr(&quot;請輸入金額&quot;)" @input="error=''"/></label><input v-model="percent" type="range" min="0" max="100" :aria-label="$tr(&quot;使用資金百分比&quot;)" @input="amount=String(session.mode==='模擬'?100000*percent/100:0)"/><div class="summary-line mini-label"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><dl class="details-list"><dt>{{ $tr("預估保證金") }}</dt><dd>{{ $tr(fmt((Number(amount)||0)/Number(leverage))) }}{{ $tr(" USD") }}</dd><dt>{{ $tr("可用餘額") }}</dt><dd>{{ $tr(session.mode==='模擬'?'100,000.00':'0.00') }}{{ $tr(" USD") }}</dd></dl><RouterLink class="green-link" :to="path('/assets/transfer')">{{ $tr("＋ 劃轉") }}</RouterLink><p v-if="error" role="alert" class="form-error">{{ $tr(error) }}</p><div class="two-cols order-buttons"><button class="buy" @click="order(mode==='spot'?'買入':'買入 / 開多')">{{ $tr(mode==='spot'?'買入':'買入 / 開多') }}</button><button class="sell" @click="order(mode==='spot'?'賣出':'賣出 / 開空')">{{ $tr(mode==='spot'?'賣出':'賣出 / 開空') }}</button></div><p class="mini-label">{{ $tr("本地模擬行情與委託，不連接交易服務。") }}</p></section></div>
<section class="terminal-panel records-panel"><div class="record-tabs"><button v-for="r in ['合約倉位','合約歷史倉位','合約當前委託','合約歷史委託','期權訂單','現貨委託','現貨歷史']" :class="{active:records===r}" @click="records=r">{{ $tr(r) }}</button></div><div class="filter-row"><label>{{ $tr("交易對 ") }}<select><option :value="&quot;全部&quot;">{{ $tr("全部") }}</option><option :value="pair.name">{{ $tr(pair.name) }}</option></select></label><label>{{ $tr("倉位類型 ") }}<select><option :value="&quot;全部&quot;">{{ $tr("全部") }}</option><option :value="&quot;多倉&quot;">{{ $tr("多倉") }}</option><option :value="&quot;空倉&quot;">{{ $tr("空倉") }}</option></select></label></div><div v-if="!session.orders.length" class="empty">{{ $tr("暫無倉位") }}<p>{{ $tr("開倉後，你的合約倉位與即時盈虧會顯示在這裡。") }}</p></div><div v-for="(o,i) in session.orders" :key="i" class="demo-order"><span>{{ $tr(o.name) }}</span><span>{{ $tr(o.amount) }} {{ $tr(o.symbol) }}</span><span class="positive">{{ $tr("演示已提交") }}</span></div></section><div class="terminal-status"><span class="positive">{{ $tr("● 連線穩定 · 本地演示") }}</span><span>{{ $tr("市場快照 · ") }}{{ $tr(pair.name) }} {{ $tr(fmt(pair.price)) }}</span></div></div></template>
<style scoped>.trading-terminal{padding:0 4px 8px}.instrument-bar{display:flex;align-items:center;gap:24px;min-height:70px;padding:12px 20px;flex-wrap:wrap}.instrument-bar>strong{font-size:1.375rem}.instrument-bar small{display:block;color:#fff6;font-size:0.625rem;margin-bottom:4px}.instrument-bar>a{margin-left:auto;color:var(--nt-accent)}.terminal-grid{display:grid;grid-template-columns:21% 32% 22% 1fr;gap:4px}.terminal-panel{border:1px solid #ffffff0b;border-radius:16px;background:#080b10;min-width:0}.pair-panel{padding:12px}.pair-panel>input{width:100%;min-height:32px}.trade-modes{display:flex;gap:20px;border-bottom:1px solid #ffffff0b;padding:16px 0;font-size:0.875rem}.trade-modes .active{color:#fff;border-bottom:2px solid #fff}.trade-modes a{color:#fff6;padding-bottom:5px}.pair-categories{display:flex;gap:14px;font-size:0.75rem;padding:16px 0;flex-wrap:wrap}.pair-categories .active,.timeframes .active{color:var(--nt-accent)}.pair-categories button{color:#fff6}.pair-list{max-height:460px;overflow:auto}.pair-row{display:flex;gap:10px;padding:11px 0}.pair-row>button{color:#fff6}.pair-row>a{display:flex;justify-content:space-between;flex:1;gap:8px}.pair-row small{display:block;text-align:right;font-size:0.6875rem;margin-top:3px}.chart-panel{display:flex;flex-direction:column;overflow:hidden}.chart-panel canvas{flex:1}.timeframes{display:flex;gap:12px;flex-wrap:wrap;padding:16px 12px;font-size:0.6875rem;color:#fff7}.orderbook{padding:16px 12px}.orderbook h2{font-size:0.875rem;margin-bottom:16px}.book-head,.book-row{display:grid;grid-template-columns:1.4fr 1fr 1fr;text-align:right;font:11px 'IBM Plex Mono',monospace;padding:6px 0;position:relative}.book-row:before{content:'';position:absolute;right:0;top:0;bottom:0;width:var(--depth);background:#e34a6810;pointer-events:none}.book-row.bid:before{background:#5bbb9110}.book-head{color:#fff6;font:10px 'Exo 2',sans-serif}.book-head>span:first-child,.book-row>span:first-child{text-align:left}.book-price{font-size:1.5rem;padding:20px 0}.book-price small{display:block;font-size:0.6875rem;color:#fff6;margin-top:4px}.order-panel{padding:0 16px 20px;display:grid;gap:16px}.order-panel label{font-size:0.75rem;color:#fff8}.order-panel .two-cols{gap:8px}.order-panel .details-list{margin:0;font-size:0.6875rem}.order-panel .tabs button{border:0;border-radius:24px;padding:6px 16px;background:#ffffff08}.order-buttons button{padding:12px 5px;border-radius:8px;color:#fff;font-size:0.75rem}.buy{background:#2b8e65}.sell{background:#b53951}.records-panel{margin-top:4px}.records-panel .filter-row{margin:16px}.demo-order{padding:16px;display:flex;justify-content:space-between;gap:16px;border-top:1px solid #ffffff0b}.terminal-status{display:flex;justify-content:space-between;font-size:0.6875rem;padding:12px 8px;color:#fff7}@media(max-width:1150px){.terminal-grid{grid-template-columns:23% 1fr 30%}.orderbook{grid-column:1;grid-row:2}.order-panel{grid-column:3;grid-row:1/3}.chart-panel{grid-column:2;grid-row:1/3}.pair-panel{grid-column:1}.pair-list{max-height:260px}.instrument-bar{gap:16px}}@media(max-width:750px){.terminal-grid{grid-template-columns:1fr 1fr}.chart-panel{grid-column:1/3;grid-row:1;height:380px}.order-panel{grid-column:1/3;grid-row:2}.pair-panel{grid-column:1;grid-row:3}.orderbook{grid-column:2;grid-row:3}.instrument-bar{padding:12px;gap:14px;font-size:0.6875rem}.instrument-bar .coin-label{font-size:1rem}.instrument-bar>strong{font-size:1.125rem}.instrument-bar>a{margin-left:0}.pair-row{font-size:0.6875rem}.pair-categories{gap:8px}.trade-modes{gap:12px}.pair-list{max-height:440px}.book-row{font-size:0.5625rem}.book-price{font-size:1.125rem}.book-head{font-size:0.5625rem}.terminal-status{gap:16px}.records-panel .record-tabs{gap:14px;font-size:0.75rem}.demo-order{font-size:0.75rem;flex-wrap:wrap}}
@media(min-width:1151px){.trading-terminal{display:grid;grid-template-columns:21% 32% 22% 1fr;grid-template-rows:64px 500px minmax(280px,1fr) auto;gap:4px;min-height:calc(100dvh - 64px)}.terminal-grid{display:contents}.instrument-bar{grid-column:1/3;grid-row:1;gap:12px;padding:10px 12px;min-height:0;font-size:0.6875rem}.instrument-bar>strong{font-size:1.125rem}.instrument-bar .coin{width:28px;height:28px}.instrument-bar .coin-label{font-size:1rem}.instrument-bar small{font-size:0.5625rem}.instrument-bar>a{font-size:0.625rem}.pair-panel{grid-column:1;grid-row:2;padding:12px}.chart-panel{grid-column:2;grid-row:2}.orderbook{grid-column:3;grid-row:1/3}.order-panel{grid-column:4;grid-row:1/3;gap:10px;align-content:start;font-size:0.75rem}.order-panel .trade-modes{padding:12px 0;font-size:0.75rem}.order-panel .two-cols{grid-template-columns:1fr}.order-panel .order-buttons{grid-template-columns:1fr 1fr}.order-panel input,.order-panel select{min-height:32px;padding:7px 12px}.order-panel label{gap:4px}.order-panel .tabs button{flex:1;border-radius:4px}.order-panel .tabs button.active{background:#5bbb91;color:#fff}.order-panel .summary-line{font-size:0.625rem}.order-panel .details-list{gap:10px}.order-panel .tag-chip{padding:2px 8px}.order-panel .mini-label{font-size:0.625rem}.order-panel input[type=range]{min-height:16px;padding:0}.records-panel{grid-column:1/-1;grid-row:3;margin:0}.records-panel .record-tabs{font-size:0.75rem;padding:8px 16px;gap:16px}.records-panel .filter-row{font-size:0.6875rem;margin:10px 16px}.records-panel select{min-height:24px;font-size:0.6875rem;padding:3px 8px;background:transparent}.records-panel .empty{padding:60px 20px}.terminal-status{grid-column:1/-1;grid-row:4}.pair-list{max-height:370px}.pair-row{font-size:0.75rem;padding:7px 0}.pair-row .coin{width:26px;height:26px}.pair-row .coin-label{font-size:0.75rem;gap:7px}.pair-row small{text-align:left;font-size:0.625rem}.pair-row>a>span:last-child small{text-align:right}.pair-categories{gap:12px;padding:12px 0;font-size:0.6875rem}.trade-modes{padding:12px 0;font-size:0.75rem}.book-row{padding:5px 0;font-size:0.6875rem}.book-price{padding:18px 0}.book-head{font-size:0.625rem}.orderbook h2{margin-bottom:12px}.orderbook{padding:16px 12px}}
</style>
